import{_ as e,c as l,o,ag as i}from"./chunks/framework.C8hRoDJf.js";const t="/docs/assets/1.CMKzCm5N.png",d="/docs/assets/2.CsAsqWV2.png",_=JSON.parse('{"title":"中心城镇","description":"","frontmatter":{},"headers":[],"relativePath":"game/central-town.md","filePath":"game/central-town.md"}'),r={name:"game/central-town.md"};function c(n,a,h,s,u,m){return o(),l("div",null,a[0]||(a[0]=[i('<h1 id="中心城镇" tabindex="-1">中心城镇 <a class="header-anchor" href="#中心城镇" aria-label="Permalink to &quot;中心城镇&quot;">​</a></h1><h2 id="地图一" tabindex="-1">地图一 <a class="header-anchor" href="#地图一" aria-label="Permalink to &quot;地图一&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><h3 id="神秘商店" tabindex="-1">神秘商店 <a class="header-anchor" href="#神秘商店" aria-label="Permalink to &quot;神秘商店&quot;">​</a></h3><ul><li>可以在神秘商店消耗<code>水晶</code>购买礼包道具。</li><li>礼包道具有概率开启到高级装备、宠物卵等高价值道具。</li></ul><h3 id="道具商店" tabindex="-1">道具商店 <a class="header-anchor" href="#道具商店" aria-label="Permalink to &quot;道具商店&quot;">​</a></h3><ul><li>可以在道具商店消耗<code>金币</code>，<code>威望</code>购买绝大部分道具。</li><li><strong>金币商店</strong>可以买到<code>精灵球</code>、<code>技能书</code>、<code>龙珠</code>......</li><li><strong>威望商店</strong>可以买到<code>天界的精髓</code>、<code>女神圣水</code>、<code>宠物卵</code>、<code>神宠进化材料</code>.....</li></ul><h3 id="铁匠铺" tabindex="-1">铁匠铺 <a class="header-anchor" href="#铁匠铺" aria-label="Permalink to &quot;铁匠铺&quot;">​</a></h3><ul><li>可以在铁匠铺消耗<code>威望</code>购买威望套装以及打造装备，提升装备的材料。</li><li>可以通过消耗<code>龙珠</code>进行装备强化。</li><li>可以把部分装备进行分解获取碎片，在任务中心兑换指定装备。</li><li>可以将低等级龙珠提升为高等级龙珠。</li></ul><h3 id="牧场" tabindex="-1">牧场 <a class="header-anchor" href="#牧场" aria-label="Permalink to &quot;牧场&quot;">​</a></h3><ul><li>可以将多余的宠物存放到牧场中。</li><li>可以在牧场把不需要的宠物进行抛弃。</li><li>可以使用<code>牧场升级卷轴</code>提高宠物存放上限。</li></ul><h3 id="仓库" tabindex="-1">仓库 <a class="header-anchor" href="#仓库" aria-label="Permalink to &quot;仓库&quot;">​</a></h3><ul><li>可以将多余的道具存放到仓库中。</li><li>可以使用<code>仓库升级卷轴</code>提高仓库道具存放上限。</li></ul><h3 id="公告牌" tabindex="-1">公告牌 <a class="header-anchor" href="#公告牌" aria-label="Permalink to &quot;公告牌&quot;">​</a></h3><ul><li>可以查看<code>玩家守则</code>。</li><li>可以为游戏买单，对服务器开支进行赞赏。</li></ul><h3 id="皇宫" tabindex="-1">皇宫 <a class="header-anchor" href="#皇宫" aria-label="Permalink to &quot;皇宫&quot;">​</a></h3><ul><li>可以领取<code>每日福利礼包</code>，<code>周末福利礼包</code>，<code>节日限定礼包</code>。</li></ul><h2 id="地图二" tabindex="-1">地图二 <a class="header-anchor" href="#地图二" aria-label="Permalink to &quot;地图二&quot;">​</a></h2><p><img src="'+d+'" alt=""></p><h3 id="宠物神殿" tabindex="-1">宠物神殿 <a class="header-anchor" href="#宠物神殿" aria-label="Permalink to &quot;宠物神殿&quot;">​</a></h3><ul><li>可以消耗金币及宠物进化材料，进行宠物进化。</li><li>可以消耗金币及宠物合成材料，将两只五系宠物进行合成。</li><li>可以消耗金币及宠物涅磐材料，将两只神系宠物及一只涅磐兽进行涅磐。</li><li>可以消耗神宠进化材料进行神宠二次进化。</li></ul><h3 id="摩卡志" tabindex="-1">摩卡志 <a class="header-anchor" href="#摩卡志" aria-label="Permalink to &quot;摩卡志&quot;">​</a></h3><ul><li>在游戏过程中，玩家满足一定的<code>道具收集</code>，<code>怪物击败</code>，<code>宠物收集</code>条件后可以领取永久勋章，勋章佩戴后，在公屏聊天时生效。</li></ul>',23)]))}const b=e(r,[["render",c]]);export{_ as __pageData,b as default};
